  if(a==='company-growth'){const[id,code]=k.split('|');u.companyOffer=code;u.companyOfferAccount=id;close();navigate({page:'relationships',client:id,tab:'growth'});const url=new URL(location.href);url.searchParams.set('product',code);window.history.replaceState(null,'',url);render();}
